const view=document.querySelector('#view'),message=document.querySelector('#message');const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let catalogue=[];const orderRef=o=>o.display_id||o.id;
let loadingCount=0;const saving=new Set();
async function api(path,method='GET',body){const key=method+':'+path;if(method!=='GET'&&saving.has(key))throw Error('A save is already in progress. Please wait.');if(method!=='GET')saving.add(key);loadingCount++;document.querySelector('#loading').textContent='Loading…';try{const r=await fetch('/api/'+path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await r.json()}catch{throw Error('Session expired or server unavailable. Refresh and sign in again.')}if(!r.ok)throw Error(data.error||'Request failed');return data}finally{saving.delete(key);loadingCount--;document.querySelector('#loading').textContent=loadingCount?'Loading…':''}}
let me; const allowed=p=>me?.permissions.includes(p); function fail(e){message.textContent=e.message}function say(t){message.textContent=t}function field(label,name,value='',type='text'){return `<label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" required>`}
async function products(){try{catalogue=await api('admin/products');view.innerHTML=`<section><h2>Products & inventory</h2>${allowed('products.write')?'<button onclick="editProduct()">Add product</button>':''}<div class="filtergrid"><div><label for="cataloguesearch">Search product / SKU / category</label><input id="cataloguesearch"></div><div><label for="stockfilter">Stock & status</label><select id="stockfilter"><option value="">All products</option><option value="low">Low stock (1–5)</option><option value="zero">Out of stock</option><option value="active">Active</option><option value="draft">Draft</option><option value="archived">Archived</option></select></div></div><div class="scroll"><table><tr><th>Product</th><th>SKU</th><th>Price</th><th>Stock</th><th>Unit weight</th><th>Status</th><th></th></tr>${catalogue.map((p,i)=>`<tr data-catalogue-row="${i}"><td>${esc(p.name)}${p.variant_label?'<br><small>'+esc(p.variant_label)+'</small>':''}</td><td>${esc(p.sku)}</td><td>৳${p.price}</td><td><span class="badge ${p.stock===0?'danger':p.stock<=5?'warning':''}">${p.stock===0?'Out of stock':p.stock<=5?'Low stock: '+p.stock:p.stock}</span></td><td>${p.weight_grams?esc(p.weight_grams)+' g':'Missing weight'}</td><td>${p.status}</td><td>${allowed('products.write')?`<button onclick="editProduct(${i})">Edit</button>`:''}</td></tr>`).join('')}</table></div><p>${catalogue.length?'':'No products yet. Add your first product.'}</p></section>`;const filter=()=>{const q=document.querySelector('#cataloguesearch').value.toLowerCase(),status=document.querySelector('#stockfilter').value;document.querySelectorAll('[data-catalogue-row]').forEach(row=>{const p=catalogue[Number(row.dataset.catalogueRow)];row.hidden=!(p.name+' '+p.sku+' '+p.category+' '+p.variant_label).toLowerCase().includes(q)||(status==='low'?p.stock<1||p.stock>5:status==='zero'?p.stock!==0:status?status!==p.status:false)})};document.querySelector('#cataloguesearch').oninput=filter;document.querySelector('#stockfilter').onchange=filter;}catch(e){fail(e)}}
function editProduct(i){const p=catalogue[i]||{};let photos=[...new Set([p.image,...JSON.parse(p.images||'[]')].filter(Boolean))];let cover=p.image||photos[0]||'';view.innerHTML=`<section><h2>${p.id?'Edit':'Add'} product</h2><form id="productform">${field('Product name','name',p.name)}<label for="sku">SKU (blank = automatic)</label><input id="sku" name="sku" value="${esc(p.sku||'')}"><label for="productslug">Product URL slug (blank = keep / generate)</label><input id="productslug" name="slug" value="${esc(p.slug||'')}" maxlength="100"><p>Changing an existing slug changes the shareable product link.</p>${field('Selling price (BDT)','price',p.price??150,'number')}<label for="compareAt">Original price (optional; higher than selling price)</label><input id="compareAt" name="compareAt" type="number" min="1" step="1" value="${p.compare_at||''}">${field('Unit weight (grams)','weightGrams',p.weight_grams??'','number')}${field('Stock quantity','stock',p.stock||0,'number')}${field('Category','category',p.category||'Bracelets')}<p><button type="button" id="managecategories">Manage categories</button></p><label for="parentId">Base product (optional — for a variant)</label><select id="parentId" name="parentId"><option value="">Standalone / base</option>${catalogue.filter(c=>!c.parent_id&&c.id!==p.id).map(c=>`<option value="${c.id}" ${c.id===p.parent_id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><label for="variantLabel">Variant details (colour / size / letter)</label><input id="variantLabel" name="variantLabel" value="${esc(p.variant_label||'')}" maxlength="120"><p>Every variant has its own SKU, price, stock, photos and unit weight. Keep non-sellable base products in Draft.</p><label for="shortDescription">Short description</label><textarea id="shortDescription" name="shortDescription" maxlength="500">${esc(p.short_description||'')}</textarea><label for="description">Full description / key features / perfect for</label><textarea id="description" name="description" rows="8" maxlength="5000">${esc(p.description||'')}</textarea><label for="material">Materials</label><input id="material" name="material" value="${esc(p.material||'')}" maxlength="500"><label for="dimensions">Size / dimensions</label><input id="dimensions" name="dimensions" value="${esc(p.dimensions||'')}" maxlength="300"><label for="care">Care instructions</label><textarea id="care" name="care" maxlength="2000">${esc(p.care||'')}</textarea><label for="tags">Tags (comma separated)</label><input id="tags" name="tags" value="${esc(JSON.parse(p.tags||'[]').join(', '))}"><label for="status">Status</label><select id="status" name="status">${['draft','active','archived'].map(s=>`<option ${p.status===s?'selected':''}>${s}</option>`).join('')}</select><h3>Product gallery</h3><p>Up to 8 photos including the cover. JPG, PNG or WebP, max 4 MB each.</p><div id="productgallery"></div><label for="imagefiles">Add photos</label><input id="imagefiles" type="file" accept="image/jpeg,image/png,image/webp" multiple><p><button>Save product</button></p></form></section>`;
document.querySelector('#category').setAttribute('list','categorynames');const suggestions=document.createElement('datalist');suggestions.id='categorynames';document.querySelector('#category').after(suggestions);api('admin/categories').then(rows=>{if(document.querySelector('#categorynames'))document.querySelector('#categorynames').innerHTML=[...new Set([...rows.map(c=>c.name),...catalogue.map(p=>p.category)])].map(name=>`<option value="${esc(name)}"></option>`).join('')}).catch(fail);
const renderPhotos=()=>{document.querySelector('#productgallery').innerHTML=photos.map((url,n)=>`<div class="checkrow"><img src="${esc(url)}" width="90" alt="Product gallery ${n+1}"><label><input type="radio" name="coverphoto" value="${n}" ${cover===url?'checked':''} style="width:auto"> Cover</label><button type="button" data-remove-photo="${n}">Remove</button></div>`).join('')||'<p>No photos added yet.</p>';document.querySelectorAll('[data-remove-photo]').forEach(b=>b.onclick=()=>{photos.splice(Number(b.dataset.removePhoto),1);if(!photos.includes(cover))cover=photos[0]||'';renderPhotos()});document.querySelectorAll('[name=coverphoto]').forEach(x=>x.onchange=()=>cover=photos[Number(x.value)])};renderPhotos();document.querySelector('#managecategories').onclick=categories;
document.querySelector('#productform').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const files=[...document.querySelector('#imagefiles').files];if(files.length+photos.length>8)throw Error('At most 8 product photos');for(const file of files){if(file.size>4194304)throw Error('Each photo must be under 4 MB');const r=await fetch('/api/admin/media',{method:'POST',headers:{'Content-Type':file.type},body:file}),result=await r.json();if(!r.ok)throw Error(result.error);photos.push(result.url)}if(!cover)cover=photos[0]||'';const d=Object.fromEntries(new FormData(e.target));await api('admin/products','POST',{...d,parentId:d.parentId||null,price:Number(d.price),compareAt:d.compareAt?Number(d.compareAt):null,stock:Number(d.stock),weightGrams:Number(d.weightGrams),tags:[...new Set(d.tags.split(',').map(s=>s.trim()).filter(Boolean))],image:cover,images:photos,...(p.id?{id:p.id}:{})});say('Product saved.');products()}catch(e){fail(e);renderPhotos();document.querySelector('#imagefiles').value=''}finally{b.disabled=false}}}
let managedCategories=[];
async function categories(){try{managedCategories=await api('admin/categories');view.innerHTML=`<section><h2>Categories</h2><p>Category names connect products to their collection. Renaming a managed category updates its products. Hide from category navigation without archiving its products.</p>${allowed('products.write')?'<button onclick="editCategory()">Add category</button>':''}<table><tr><th>Name</th><th>Products</th><th>Visible</th><th></th></tr>${managedCategories.map((c,i)=>`<tr><td>${esc(c.name)}</td><td>${c.product_count}</td><td>${c.active?'Yes':'No'}</td><td>${allowed('products.write')?`<button onclick="editCategory(${i})">Edit</button>`:''}</td></tr>`).join('')}</table><p>Existing product categories stay available automatically. Add a matching category name here to give it a description and cover image.</p></section>`}catch(e){fail(e)}}
function editCategory(i){const c=managedCategories[i]||{};view.innerHTML=`<section><h2>${c.id?'Edit':'Add'} category</h2><form id="categoryform">${field('Category name','name',c.name)}<label for="slug">URL slug (optional)</label><input id="slug" name="slug" value="${esc(c.slug||'')}"><label for="description">Category description</label><textarea id="description" name="description" maxlength="2000">${esc(c.description||'')}</textarea>${field('Display order','sortOrder',c.sort_order||0,'number')}<label><input id="categoryactive" type="checkbox" ${c.active!==0?'checked':''} style="width:auto"> Visible in categories</label><label for="categoryimage">Category photo (optional; max 4 MB)</label><input id="categoryimage" type="file" accept="image/jpeg,image/png,image/webp">${c.image?`<img src="${esc(c.image)}" width="120" alt="Category cover">`:''}<p><button>Save category</button></p></form></section>`;document.querySelector('#categoryform').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{let image=c.image||'';const file=document.querySelector('#categoryimage').files[0];if(file){if(file.size>4194304)throw Error('Photo must be under 4 MB');const r=await fetch('/api/admin/media',{method:'POST',body:file}),v=await r.json();if(!r.ok)throw Error(v.error);image=v.url}const d=Object.fromEntries(new FormData(e.target));await api('admin/categories','POST',{...d,...(c.id?{id:c.id}:{}),image,active:document.querySelector('#categoryactive').checked,sortOrder:Number(d.sortOrder)});say('Category saved.');categories()}catch(e){fail(e)}finally{b.disabled=false}}}

const orderStatuses=['Pending','On Hold','Processing','Ready to Ship','In-Transit','Delivered','Returned','Cancelled','Return Requested','Confirmed','Packed','Dispatched'];
const statusNext={Pending:['Processing','On Hold','Cancelled'],'On Hold':['Pending','Processing','Cancelled'],Processing:['Ready to Ship','On Hold','Cancelled'],'Ready to Ship':['In-Transit','On Hold','Cancelled'],'In-Transit':['Delivered','Return Requested','Returned'],Delivered:['Return Requested','Returned'],'Return Requested':['Returned'],Cancelled:[],Returned:[],Confirmed:['Processing','On Hold','Cancelled'],Packed:['Ready to Ship','Dispatched','Cancelled'],Dispatched:['In-Transit','Delivered','Return Requested','Returned']};
let orderQuery={},reportQuery={},orderPage=1;
function filterForm(query,couriers,id){return `<form id="${id}" style="max-width:none"><div class="filtergrid"><div><label for="${id}from">From</label><input type="date" id="${id}from" name="from" value="${esc(query.from||'')}"></div><div><label for="${id}to">To</label><input type="date" id="${id}to" name="to" value="${esc(query.to||'')}"></div><div><label for="${id}basis">Date basis</label><select id="${id}basis" name="basis"><option value="created" ${query.basis!=='status'?'selected':''}>Order created date</option><option value="status" ${query.basis==='status'?'selected':''}>Current status date</option></select></div><div><label for="${id}status">Order status</label><select name="status" id="${id}status"><option value="">All statuses</option>${orderStatuses.map(s=>`<option ${query.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div><label for="${id}source">Order source</label><select id="${id}source" name="source"><option value="">All sources</option>${['Website','Messenger','Instagram','Facebook','POS'].map(s=>`<option ${query.source===s?'selected':''}>${s}</option>`).join('')}</select></div><div><label for="${id}courier">Courier</label><select name="courier" id="${id}courier"><option value="">All couriers</option><option value="unassigned" ${query.courier==='unassigned'?'selected':''}>Unassigned</option>${couriers.map(c=>`<option value="${c.id}" ${query.courier===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div></div><label for="${id}q">Search order, customer, phone or tracking number</label><input id="${id}q" name="q" value="${esc(query.q||'')}" maxlength="100"><p><button>Apply filters</button> <button type="button" data-reset>Reset</button></p></form>`}
let currentOrderRows=[];async function orders(){try{const list=await api('admin/orders?'+new URLSearchParams({...orderQuery,paged:'1',page:orderPage}));currentOrderRows=list.orders;const courierData=allowed('couriers.read')?await api('admin/couriers'):[];view.innerHTML=`<section><h2>Orders (${list.total})</h2><button onclick="orders()">Refresh list</button>${filterForm(orderQuery,courierData,'orderfilters')}<div class="statuschips"><button data-status="">All</button>${orderStatuses.map(s=>`<button data-status="${s}" class="${orderQuery.status===s?'selected':''}">${s} (${list.status.find(r=>r.status===s)?.count||0})</button>`).join('')}</div><div class="bulkbar"><label><input type="checkbox" id="selectall" style="width:auto"> Select this page</label><label for="bulkstatus">Next status</label><select id="bulkstatus"><option value="">Choose next status</option>${orderStatuses.filter(s=>s!=='Pending').map(s=>`<option>${s}</option>`).join('')}</select><button id="bulkstatusgo" ${allowed('orders.status')?'':'disabled'}>Apply status</button><label for="bulkcourier">Assign to</label><select id="bulkcourier"><option value="">Choose courier</option>${courierData.filter(c=>c.active).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><button id="bulkcouriergo" ${allowed('orders.edit')?'':'disabled'}>Assign courier</button><button id="bulkinvoice">Print invoices</button><button id="bulkslip">Print packing slips</button></div><p id="bulkresult" role="status"></p><div class="scroll"><table><thead><tr><th>Select</th><th>Order / date</th><th>Customer</th><th>Source</th><th>Courier / tracking</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>${list.orders.map(o=>`<tr><td><input type="checkbox" data-select-order="${o.id}" aria-label="Select ${esc(orderRef(o))}" style="width:auto"></td><td>${esc(orderRef(o))}<br>${esc(new Date(o.created_at).toLocaleDateString('en-GB',{timeZone:'Asia/Dhaka'}))}</td><td>${esc(o.name)}<br>${esc(o.phone)}</td><td>${esc(o.source)}</td><td>${esc(o.courier_name||'Unassigned')}<br>${esc(o.consignment||'No tracking number')}<br>API payment: ${esc(o.courier_payment_status||'Not synced')}<br>Settlement: ${esc(o.manual_settlement_status||'Not recorded')}${o.tracking_url?`<br><a href="${esc(o.tracking_url)}" target="_blank" rel="noopener">Track parcel ↗</a>`:''}</td><td>৳${o.total}</td><td><span class="badge">${esc(o.status)}</span></td><td><button data-id="${o.id}">Open</button> ${allowed('orders.status')?`<button data-manual-status="${o.id}">Update status</button>`:''}</td></tr>`).join('')}</tbody></table></div>${list.total?'':'<p>No orders match these filters.</p>'}<p>Page ${list.page} of ${list.pages} · Times in Bangladesh time</p><button id="prevpage" ${list.page>1?'':'disabled'}>Previous</button> <button id="nextpage" ${list.page<list.pages?'':'disabled'}>Next</button></section>`;
 document.querySelector('#selectall').onchange=e=>document.querySelectorAll('[data-select-order]').forEach(c=>c.checked=e.target.checked);document.querySelector('#bulkstatusgo').onclick=()=>bulkAction('status');document.querySelector('#bulkcouriergo').onclick=()=>bulkAction('courier');document.querySelector('#bulkinvoice').onclick=()=>bulkPrint('invoice');document.querySelector('#bulkslip').onclick=()=>bulkPrint('packing');document.querySelector('#orderfilters').onsubmit=e=>{e.preventDefault();orderQuery=Object.fromEntries(new FormData(e.target));orderPage=1;orders()};document.querySelector('[data-reset]').onclick=()=>{orderQuery={};orderPage=1;orders()};document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{orderQuery.status=b.dataset.status;orderPage=1;orders()});document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>detail(b.dataset.id));document.querySelectorAll('[data-manual-status]').forEach(b=>b.onclick=()=>manualStatus(b.dataset.manualStatus));document.querySelector('#prevpage').onclick=()=>{orderPage--;orders()};document.querySelector('#nextpage').onclick=()=>{orderPage++;orders()};}catch(e){fail(e)}}

async function detail(id){try{const d=await api('admin/orders/'+id),o=d.order;const next=statusNext;view.innerHTML=`<section><button onclick="orders()">← Back to orders</button><h2>${esc(orderRef(o))}</h2><p>${esc(o.name)} · ${esc(o.phone)}</p><p>${esc(o.address)}</p><p>Notes: ${esc(o.notes)}</p><p>${esc(o.source)} · ${esc(o.status)} · Cash on Delivery</p>${d.items.map(i=>`<p>${esc(i.name)} × ${i.qty} — ৳${i.price*i.qty}</p>`).join('')}<p>Subtotal ৳${o.subtotal} − discount ৳${o.discount||0} + delivery ৳${o.shipping}</p><h3>Total ৳${o.total}</h3><h3>Manual status update</h3><label for="newstatus">Next allowed status</label><select id="newstatus">${next[o.status].map(s=>`<option>${s}</option>`).join('')}</select><p><button id="updatestatus" ${next[o.status].length&&allowed('orders.status')?'':'disabled'}>Update status</button></p>${o.status==='Returned'&&allowed('returns.read')?`<p><button onclick="returnDetail('${o.id}')">Receive return / Courier inquiry</button></p>`:''}<h3>Status history</h3>${d.history.map(h=>`<p>${esc(h.status)} · ${esc(new Date(h.at).toLocaleString('en-GB',{timeZone:'Asia/Dhaka'}))}</p>`).join('')}<p>Cancelled orders release reserved stock. Returned orders enter Return receiving; only inspected good quantities are restocked.</p><p><button id="invoice">Invoice / Print / PDF</button> <button id="orderops">Discount / Payments / Packing / Courier</button> ${allowed('orders.edit')&&['Pending','On Hold','Confirmed','Processing','Packed','Ready to Ship'].includes(o.status)?'<button id="editorder">Edit customer & courier</button>':''}</p><p>Live courier API status is not connected yet. The status above is managed in this store.</p><p>Courier: ${esc(o.courier_name||'Unassigned')} · Consignment: ${esc(o.consignment)} · Weight: ${o.weight_grams?o.weight_grams/1000+' kg':'Not set'}</p>${o.tracking_url?`<a href="${esc(o.tracking_url)}" target="_blank" rel="noopener">Track parcel ↗</a>`:''}</section>`;document.querySelector('#invoice').onclick=()=>invoice(d);document.querySelector('#orderops').onclick=()=>orderOperations(id);if(document.querySelector('#editorder'))document.querySelector('#editorder').onclick=()=>editOrder(o);document.querySelector('#updatestatus').onclick=async()=>{try{await api('admin/orders/'+id,'PATCH',{status:document.querySelector('#newstatus').value});say('Status updated.');detail(id)}catch(e){fail(e)}}}catch(e){fail(e)}}
async function newOrder(){try{catalogue=await api('admin/products');const active=catalogue.filter(p=>p.status==='active');posActive=active;if(!active.length){say('Add an active product with stock before creating an order.');return products()}const delivery=await api('shipping');const courierOptions=allowed('couriers.read')?(await api('admin/couriers')).filter(c=>c.active):[];const draftKey='siore-pos-'+me.id;let draft;try{draft=JSON.parse(sessionStorage.getItem(draftKey)||'null')}catch{}const key=draft?.key||crypto.randomUUID();view.innerHTML=`<section><h2>POS / DM order entry</h2><p class="notice">Draft is kept in this tab until submitted or cleared.</p><button type="button" id="cleardraft">Clear draft</button><form id="orderform">${field('Customer name','name')}${field('Phone','phone','','tel')}<div id="customerhistory" aria-live="polite"></div>${field('Full delivery address','address')}<label for="source">Source</label><select name="source" id="source"><option>Messenger</option><option>Instagram</option><option>Facebook</option><option>POS</option><option>Website</option></select><label for="zone">Delivery zone</label><select name="zone" id="zone"><option value="inside">Inside Dhaka</option><option value="outside">Outside Dhaka</option></select><p>New orders start Pending. Courier booking happens after Ready to Ship.</p><label for="newcourier">Courier (optional)</label><select id="newcourier" name="courierId"><option value="">Assign later</option>${courierOptions.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><h3>Order items</h3><p>Add multiple products or variants. Each selected item has its own quantity and stock limit.</p><label for="productsearch">Search name, SKU, colour, size or letter</label><input id="productsearch" placeholder="Search products"><label for="posproduct">Choose a product / variant</label><select id="posproduct"></select><p><button type="button" id="posaddproduct">+ Add product</button></p><div id="positems"></div><p id="posempty">No items added yet. Choose a product and press Add product.</p><label for="notes">Notes</label><textarea name="notes" id="notes"></textarea>${allowed('payments.write')?'<label for="advance">Advance received (BDT)</label><input id="advance" name="advance" type="number" min="0" step="1" value="0"><label for="advanceReference">Advance transaction reference</label><input id="advanceReference" name="advanceReference" maxlength="200">':''}${allowed('orders.edit')?'<label for="discount">Manual discount (BDT)</label><input id="discount" name="discount" type="number" min="0" step="1" value="0">':''}<p id="posweight"></p><h3 id="postotal"></h3><p>Final prices and delivery charges are verified on the server.</p><button>Create COD order</button></form></section>`;function recalc(){const subtotal=[...document.querySelectorAll('[data-product]')].reduce((sum,x)=>sum+Number(x.value)*Number(x.dataset.price),0);const fee=delivery[document.querySelector('#zone').value];const discount=Number(document.querySelector('#discount')?.value||0);const qty=[...document.querySelectorAll('[data-product]')].filter(x=>Number(x.value)>0);const missing=qty.some(x=>!active.find(p=>p.id===x.dataset.product)?.weight_grams);const grams=qty.reduce((n,x)=>n+(active.find(p=>p.id===x.dataset.product)?.weight_grams||0)*Number(x.value),0);document.querySelector('#posweight').textContent='Auto product weight: '+(missing?'Missing product weight — update Products before shipping':grams+' g');if(document.querySelector('#discount'))document.querySelector('#discount').max=subtotal;document.querySelector('#postotal').textContent='Subtotal ৳'+subtotal+' − discount ৳'+discount+' + delivery ৳'+fee+' = ৳'+(subtotal+fee-discount)+' · COD due ৳'+Math.max(0,subtotal+fee-discount-Number(document.querySelector('#advance')?.value||0))}document.querySelectorAll('[data-product]').forEach(x=>x.oninput=recalc);document.querySelector('#zone').onchange=recalc;if(document.querySelector('#advance'))document.querySelector('#advance').oninput=recalc;if(document.querySelector('#discount'))document.querySelector('#discount').oninput=recalc;posRecalc=recalc;function picker(){const q=document.querySelector('#productsearch').value.toLowerCase();const options=active.filter(p=>(p.name+' '+p.sku+' '+p.variant_label).toLowerCase().includes(q));document.querySelector('#posproduct').innerHTML='<option value="">Select product</option>'+options.map(p=>`<option value="${p.id}" ${p.stock>0?'':'disabled'}>${esc(p.name)}${p.variant_label?' — '+esc(p.variant_label):''} · ${esc(p.sku)} · ৳${p.price} · Stock ${p.stock}</option>`).join('')}document.querySelector('#productsearch').oninput=picker;picker();document.querySelector('#posaddproduct').onclick=()=>{const id=document.querySelector('#posproduct').value;if(!id)return say('Select an in-stock product first.');appendPosItem(id,1,true)};recalc();setupPosDraft(draftKey,key,draft,recalc);document.querySelector('#orderform').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));const items=[...document.querySelectorAll('[data-product]')].filter(x=>Number(x.value)>0).map(x=>({productId:x.dataset.product,qty:Number(x.value)}));const o=await api('orders','POST',{...data,discount:Number(data.discount||0),advance:Number(data.advance||0),courierId:data.courierId||null,requestKey:key,items});sessionStorage.removeItem(draftKey);say('Order saved: '+orderRef(o)+' · Total ৳'+o.total);detail(o.id)}catch(e){fail(e)}finally{b.disabled=false}}}catch(e){fail(e)}}
async function shipping(){try{const s=await api('shipping');view.innerHTML=`<section><h2>Delivery settings</h2><form id="shippingform">${field('Inside Dhaka (BDT)','inside',s.inside,'number')}${field('Outside Dhaka (BDT)','outside',s.outside,'number')}<p><button>Save charges</button></p></form></section>`;document.querySelector('#shippingform').onsubmit=async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));await api('admin/shipping','POST',{inside:Number(d.inside),outside:Number(d.outside)});say('Delivery charges saved.')}catch(e){fail(e)}}}catch(e){fail(e)}}boot();
async function boot(){try{me=await api('admin/me');document.querySelector('#identity').textContent=me.name+' · '+me.role+' · '+me.email;if(me.role==='Owner'){for(let batch=0;batch<20;batch++){const numbering=await api('admin/ops/number-orders','POST',{});if(!numbering.remaining)break}}const tabs=[['Dashboard',allowed('orders.read.all')?'orders.read.all':'orders.read.own','dashboard()'],['Products & inventory','products.read','products()'],['Categories','products.read','categories()'],['Orders',allowed('orders.read.all')?'orders.read.all':'orders.read.own','orders()'],['POS / DM order','orders.create','newOrder()'],['Couriers','couriers.read','couriers()'],['Staff & permissions','users.manage','users()'],['Delivery settings','shipping.write','shipping()'],['Follow-ups',allowed('orders.read.all')?'orders.read.all':'orders.read.own','followups()'],['Courier checks',allowed('orders.read.all')?'orders.read.all':'orders.read.own','courierChecks()'],['Settlements','settlements.write','settlementReport()'],['Return receiving','returns.read','returnQueue()'],['Return inquiries','returns.read',"returnQueue('inquiry')"],['Return report','reports.read','returnReport()'],['Reports','reports.read','reports()'],['Activity log','audit.read','audit()']];document.querySelector('#tabs').innerHTML=tabs.filter(t=>allowed(t[1])).map(t=>`<button onclick="${t[2]}">${t[0]}</button>`).join('');if(allowed('orders.read.all')||allowed('orders.read.own'))dashboard();else if(allowed('orders.create'))newOrder();else if(allowed('products.read'))products();else if(allowed('returns.read'))returnQueue();else say('Your account has no workspace permissions. Contact the owner.')}catch(e){fail(e)}}
let staffList=[];
async function users(){try{staffList=await api('admin/users');view.innerHTML=`<section><h2>Staff & access permissions</h2><p>The owner retains full access. Staff permissions are checked on every API request. Disable a user to revoke application access.</p><p class="notice">This site is private. Staff also need an invitation through the Site sharing settings using the same email. Adding a staff record here does not send an invitation or change Site access.</p><button onclick="editUser()">Add staff user</button><div class="scroll"><table><tr><th>Name / email</th><th>Role</th><th>Status</th><th></th></tr>${staffList.map((u,i)=>`<tr><td>${esc(u.name)}<br>${esc(u.email)}</td><td>${esc(u.role)}</td><td>${u.active?'Active':'Disabled'}</td><td><button onclick="editUser(${i})">Edit access</button></td></tr>`).join('')}</table></div></section>`}catch(e){fail(e)}}
function editUser(i){const u=staffList[i]||{permissions:me.roles.Moderator,role:'Moderator',active:1};view.innerHTML=`<section><h2>${u.id?'Edit':'Add'} staff user</h2><form id="staffform">${field('Name','name',u.name)}${field('ChatGPT sign-in email','email',u.email,'email')}<label for="role">Role preset</label><select id="role" name="role">${Object.keys(me.roles).map(r=>`<option ${r===u.role?'selected':''}>${r}</option>`).join('')}</select><label><input type="checkbox" id="staffactive" style="width:auto" ${u.active?'checked':''}> Active account</label><h3>Permissions</h3><p>“Read own orders” limits order access and editing to that staff member’s orders. Grant “Read all orders” only when needed.</p><div id="permissions">${me.availablePermissions.map(p=>`<label><input type="checkbox" data-permission="${p}" style="width:auto" ${u.permissions.includes(p)?'checked':''}> ${esc(permissionNames[p]||p)} <small>(${p})</small></label>`).join('')}</div><p><button>Save user & permissions</button></p></form></section>`;document.querySelector('#role').onchange=e=>{const preset=me.roles[e.target.value];document.querySelectorAll('[data-permission]').forEach(x=>x.checked=preset.includes(x.dataset.permission))};document.querySelector('#staffform').onsubmit=async e=>{e.preventDefault();try{await api('admin/users','POST',{...Object.fromEntries(new FormData(e.target)),...(u.id?{id:u.id}:{}),active:document.querySelector('#staffactive').checked,permissions:[...document.querySelectorAll('[data-permission]:checked')].map(x=>x.dataset.permission)});say('Staff access saved.');users()}catch(e){fail(e)}}}
let courierList=[];
async function couriers(){try{courierList=await api('admin/couriers');view.innerHTML=`<section><h2>Courier management</h2><p>Add multiple couriers and assign them to orders. Tracking links work when configured. Live API tracking and auto-booking require your courier provider and approved API access.</p>${allowed('couriers.write')?'<button onclick="editCourier()">Add courier</button> <button onclick="enableCourier(&quot;carrybee&quot;)">Enable CarryBee</button> <button onclick="enableCourier(&quot;pathao&quot;)">Enable Pathao</button>':''}<table><tr><th>Courier</th><th>Provider</th><th>Status</th><th>Tracking connection</th><th></th></tr>${courierList.map((c,i)=>`<tr><td>${esc(c.name)}</td><td>${esc(c.provider||'manual')}</td><td>${c.active?'Active':'Disabled'}</td><td>Manual tracking · Live API not connected</td><td>${allowed('couriers.write')?`<button onclick="editCourier(${i})">Edit</button> ${me.role==='Owner'&&c.provider==='carrybee'?`<button onclick="courierCredentials(${i})">API credentials</button>`:''}`:''}</td></tr>`).join('')}</table></section>`}catch(e){fail(e)}}
function editCourier(i){const c=courierList[i]||{active:1};view.innerHTML=`<section><h2>${c.id?'Edit':'Add'} courier</h2><form id="courierform">${field('Courier name','name',c.name)}<label for="provider">Courier provider</label><select id="provider" name="provider">${['manual','carrybee','pathao'].map(p=>`<option value="${p}" ${p===c.provider?'selected':''}>${p==='carrybee'?'CarryBee':p==='pathao'?'Pathao':'Other / manual'}</option>`).join('')}</select><p>Provider selection does not connect an API. Merchant API documentation and server credentials are required for live tracking.</p><p><a href="https://merchant.carrybee.com" target="_blank" rel="noopener">CarryBee merchant panel ↗</a> · <a href="https://merchant.pathao.com" target="_blank" rel="noopener">Pathao merchant panel ↗</a></p><label for="trackingTemplate">Tracking URL template (optional)</label><input id="trackingTemplate" name="trackingTemplate" value="${esc(c.tracking_template||'')}" placeholder="https://courier.example/track/{tracking}"><label><input style="width:auto" id="courieractive" type="checkbox" ${c.active?'checked':''}> Active courier</label><p><button>Save courier</button></p></form></section>`;document.querySelector('#courierform').onsubmit=async e=>{e.preventDefault();try{await api('admin/couriers','POST',{...Object.fromEntries(new FormData(e.target)),...(c.id?{id:c.id}:{}),active:document.querySelector('#courieractive').checked});say('Courier saved.');couriers()}catch(e){fail(e)}}}
async function editOrder(o){try{const list=allowed('couriers.read')?await api('admin/couriers'):[];view.innerHTML=`<section><h2>Edit order</h2><p>${esc(orderRef(o))}</p><form id="editorderform">${field('Customer name','name',o.name)}${field('Phone','phone',o.phone,'tel')}${field('Delivery address','address',o.address)}<label for="zone">Delivery area</label><select id="zone" name="zone"><option value="inside" ${o.zone==='inside'?'selected':''}>Inside Dhaka</option><option value="outside" ${o.zone==='outside'?'selected':''}>Outside Dhaka</option></select><label for="notes">Notes</label><textarea id="notes" name="notes">${esc(o.notes)}</textarea><label for="courierId">Courier</label><select id="courierId" name="courierId"><option value="">Unassigned</option>${list.filter(c=>c.active||c.id===o.courier_id).map(c=>`<option value="${c.id}" ${c.id===o.courier_id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><p>Weight is calculated automatically from product weights and quantities.</p><label for="consignment">Consignment / tracking number</label><input id="consignment" name="consignment" value="${esc(o.consignment)}"><label for="trackingUrl">Tracking URL (optional; HTTPS)</label><input id="trackingUrl" name="trackingUrl" value="${esc(o.tracking_url)}"><p>Changing delivery area recalculates the shipping fee and total. Product quantities and prices stay locked.</p><button>Save changes</button></form></section>`;document.querySelector('#editorderform').onsubmit=async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));await api('admin/orders/'+o.id,'PUT',{...d,courierId:d.courierId||null});say('Order updated.');detail(o.id)}catch(e){fail(e)}}}catch(e){fail(e)}}
async function audit(){try{const list=await api('admin/audit');view.innerHTML=`<section><h2>Staff activity log</h2><div class="scroll"><table><tr><th>Time</th><th>Staff</th><th>Action</th><th>Record</th></tr>${list.map(l=>`<tr><td>${esc(l.at)}</td><td>${esc(l.actor)}</td><td>${esc(l.action)}</td><td>${esc(l.target)}</td></tr>`).join('')}</table></div></section>`}catch(e){fail(e)}}
function invoice(d){const o=d.order;const w=window.open('','_blank');if(!w){say('Allow pop-ups to open your invoice.');return}w.document.write(`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Invoice ${esc(orderRef(o))}</title><style>body{font:14px Arial;color:#222;max-width:800px;padding:35px;margin:auto}header{display:flex;justify-content:space-between;border-bottom:1px solid #ccc;padding-bottom:20px}h1{font:44px Georgia;margin:0}p{line-height:1.7}table{width:100%;border-collapse:collapse;margin-top:25px}th,td{text-align:left;padding:14px 8px;border-bottom:1px solid #ddd}.totals{text-align:right}.muted{color:#666;font-size:12px}@media print{button{display:none}body{padding:10px}@page{margin:15mm}}</style><header><div><h1>siore✳</h1><p>Handcrafted pieces with a touch of soul.</p></div><div><h2>Invoice</h2><p>${esc(orderRef(o).replace('SIO-','INV-'))}<br>${esc(new Date(o.created_at).toLocaleDateString('en-GB',{timeZone:'Asia/Dhaka'}))}</p></div></header><p>shahadatsisir0@gmail.com · +8801616760469<br>Joypurhat Sadar, Joypurhat, Rajshahi Division, Bangladesh</p><h3>Bill / deliver to</h3><p>${esc(o.name)}<br>${esc(o.phone)}<br>${esc(o.address)}</p><p>Order: ${esc(orderRef(o))}<br>Source: ${esc(o.source)} · Status: ${esc(o.status)} · Weight: ${o.weight_grams?o.weight_grams/1000+' kg':'Not set'}</p><table><tr><th>Product / SKU</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr>${d.items.map(i=>`<tr><td>${esc(i.name)}<br><small>${esc(i.sku||'—')}</small></td><td>${i.qty}</td><td>৳${i.price}</td><td>৳${i.price*i.qty}</td></tr>`).join('')}</table><div class="totals"><p>Subtotal: ৳${o.subtotal}<br>Discount: −৳${o.discount||0}<br>Delivery: ৳${o.shipping}</p><h2>Total: ৳${o.total}</h2><p>Recorded receipts less refunds: ৳${d.finance?.paid||0}<br>Balance due: ৳${d.finance?.due??o.total}${d.finance?.credit?'<br>Credit: ৳'+d.finance.credit:''}</p></div><p>Payment method: Cash on Delivery<br>Payment collection is not verified by this invoice.</p><p class="muted">Thank you for choosing Siore. This is an order invoice, not a payment receipt.</p><button onclick="window.print()">Print / Save as PDF</button></html>`);w.document.close()}
async function reports(){try{if(!Object.keys(reportQuery).length){const today=new Date(Date.now()+6*3600000).toISOString().slice(0,10);reportQuery={from:today.slice(0,7)+'-01',to:today,basis:'created'}}const d=await api('admin/reports?'+new URLSearchParams(reportQuery)),s=d.summary;const courierData=allowed('couriers.read')?await api('admin/couriers'):[];
view.innerHTML=`<section><h2>Sales & order reports</h2>${filterForm(reportQuery,courierData,'reportfilters')}<p><button data-range="today">Today</button> <button data-range="week">Last 7 days</button> <button data-range="month">This month</button> <button data-range="all">All dates</button></p><p class="notice">Bangladesh time (UTC+6). These are current order statuses filtered by order creation date or the latest event for the current status. Delivered sales exclude delivery charges; they are not verified cash collection or profit. A later return moves the order from Delivered to Returned.</p><div class="metrics"><div class="metric">Total orders<strong>${s.orders}</strong></div><div class="metric">Placed order value<strong>৳${s.orderValue}</strong></div><div class="metric">Delivered orders<strong>${s.delivered.count}</strong></div><div class="metric">Delivered product sales<strong>৳${s.delivered.merchandise}</strong></div><div class="metric">Returned orders<strong>${s.returned.count}</strong></div><div class="metric">Returned product value<strong>৳${s.returned.merchandise}</strong></div><div class="metric">Cancelled orders<strong>${s.cancelled.count}</strong></div></div><h3>Status breakdown</h3><div class="scroll"><table><tr><th>Status</th><th>Orders</th><th>Product value</th><th>Delivery charge</th><th>Total value</th></tr>${d.status.map(r=>`<tr><td>${esc(r.status)}</td><td>${r.count}</td><td>৳${r.merchandise}</td><td>৳${r.delivery}</td><td>৳${r.total}</td></tr>`).join('')}</table></div><h3>Date-wise summary</h3><p><button id="exportreport">Export daily report CSV</button></p><div class="scroll"><table><tr><th>Date</th><th>Orders</th><th>Order value</th><th>Delivered</th><th>Delivered sales</th><th>Returned</th><th>Return value</th><th>Cancelled</th></tr>${d.daily.map(r=>`<tr><td>${esc(r.date)}</td><td>${r.orders}</td><td>৳${r.order_value}</td><td>${r.delivered}</td><td>৳${r.delivered_sales}</td><td>${r.returned}</td><td>৳${r.return_value}</td><td>${r.cancelled}</td></tr>`).join('')}</table></div>${d.daily.length?'':'<p>No orders match these filters.</p>'}</section>`;
document.querySelector('#reportfilters').onsubmit=e=>{e.preventDefault();reportQuery=Object.fromEntries(new FormData(e.target));reports()};document.querySelector('[data-reset]').onclick=()=>{reportQuery={};reports()};document.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{const today=new Date(Date.now()+6*3600000).toISOString().slice(0,10);reportQuery={...reportQuery,to:today};if(b.dataset.range==='today')reportQuery.from=today;if(b.dataset.range==='week')reportQuery.from=new Date(new Date(today+'T00:00:00Z').getTime()-6*86400000).toISOString().slice(0,10);if(b.dataset.range==='month')reportQuery.from=today.slice(0,7)+'-01';if(b.dataset.range==='all'){reportQuery.from='';reportQuery.to=''}reports()});
document.querySelector('#exportreport').onclick=()=>{const headers=['Date (Asia/Dhaka)','Orders','Order value (BDT)','Delivered orders','Delivered product sales (BDT)','Returned orders','Returned product value (BDT)','Cancelled orders','Date basis'];const rows=d.daily.map(r=>[r.date,r.orders,r.order_value,r.delivered,r.delivered_sales,r.returned,r.return_value,r.cancelled,d.basis]);const csv=[headers,...rows].map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='siore-report-'+(d.from||'all')+'-'+(d.to||'all')+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)};
}catch(e){fail(e)}}

async function enableCourier(provider){try{const name=provider==='carrybee'?'CarryBee':'Pathao';const list=await api('admin/couriers');const existing=list.find(c=>c.provider===provider||c.name.toLowerCase()===name.toLowerCase());await api('admin/couriers','POST',{...(existing?{id:existing.id}:{}),name:existing?.name||name,provider,trackingTemplate:existing?.tracking_template||'',active:true});say(name+' enabled for order selection. Live API is not connected.');couriers()}catch(e){fail(e)}}
const permissionNames={'products.read':'View products','products.write':'Add and edit products & stock','orders.create':'Create POS / DM orders','orders.read.own':'View own orders','orders.read.all':'View all orders','orders.edit':'Edit customer & courier before dispatch','orders.status':'Change order status','couriers.read':'View couriers','couriers.write':'Manage couriers','shipping.write':'Change delivery charges','users.manage':'Manage staff & permissions','audit.read':'View activity log','reports.read':'View reports','payments.write':'Record payments and refunds','packing.write':'Save packing checklists','courier.verify':'Record and reconcile courier status','settlements.write':'Manage courier settlements'};
async function dashboard(){try{const d=await api('admin/dashboard');const open=d.status.filter(s=>!['Delivered','Cancelled','Returned'].includes(s.status)).reduce((n,s)=>n+s.count,0);view.innerHTML=`<section><p class="eyebrow">${esc(d.scope)} · ${esc(d.date)} · Bangladesh time</p><h2>Store overview</h2><div class="metrics"><div class="metric">Today's orders<strong>${d.today.orders}</strong></div><div class="metric">Today's placed value<strong>৳${d.today.orderValue}</strong></div><div class="metric">Open orders<strong>${open}</strong></div><div class="metric">Delivered product sales · all time<strong>৳${d.all.delivered.merchandise}</strong></div><div class="metric">Returned orders · all time<strong>${d.all.returned.count}</strong></div></div><h3>Work queue</h3><div class="statuschips">${d.status.map(s=>`<button data-queue="${s.status}">${s.status} (${s.count}) ↗</button>`).join('')}</div>${allowed('orders.create')?'<p><button onclick="newOrder()">+ Create POS / DM order</button></p>':''}<p>Placed value is not payment collected or profit. Delivered sales exclude delivery charges.</p>${allowed('products.read')?`<h3>Stock alerts</h3><p>Active products with 5 or fewer units. Showing up to 20.</p>${d.lowStock.length?`<table><tr><th>Product</th><th>SKU</th><th>Available</th></tr>${d.lowStock.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.sku)}</td><td><span class="badge ${p.stock===0?'danger':'warning'}">${p.stock}</span></td></tr>`).join('')}</table>`:'<p>No low-stock active products.</p>'}<p><button onclick="products()">Manage inventory ↗</button></p>`:''}<h3>Integrations</h3><p>CarryBee / Pathao: manual assignment and tracking links. Live API, payments and SMS are awaiting setup.</p></section>`;document.querySelectorAll('[data-queue]').forEach(b=>b.onclick=()=>{orderQuery={status:b.dataset.queue};orderPage=1;orders()})}catch(e){fail(e)}}
function setupPosDraft(storageKey,key,draft,recalc){const form=document.querySelector('#orderform');if(draft){for(const [id,qty] of Object.entries(draft.qty||{})){if(Number(qty)>0)appendPosItem(id,Number(qty),false)}for(const [name,value] of Object.entries(draft.fields||{})){const el=form.elements.namedItem(name);if(el)el.value=value}for(const el of form.querySelectorAll('[data-product]')){if(draft.qty?.[el.dataset.product]!=null)el.value=Math.min(Number(draft.qty[el.dataset.product]),Number(el.max))}recalc()}
function save(){const qty=Object.fromEntries([...form.querySelectorAll('[data-product]')].map(el=>[el.dataset.product,el.value]));try{sessionStorage.setItem(storageKey,JSON.stringify({key,fields:Object.fromEntries(new FormData(form)),qty}))}catch{say('Draft could not be saved in this browser tab.')}}form.addEventListener('input',save);form.addEventListener('change',save);document.querySelector('#cleardraft').onclick=()=>{sessionStorage.removeItem(storageKey);newOrder()};form.querySelector('#phone').onblur=async e=>{const target=document.querySelector('#customerhistory');if(!allowed('orders.read.own')&&!allowed('orders.read.all'))return;try{const d=await api('admin/customer-history?phone='+encodeURIComponent(e.target.value));if(!target.isConnected)return;target.innerHTML=`<p class="notice">Customer history (${esc(d.scope)}): ${d.stats.orders} order(s), ${d.stats.delivered||0} delivered, ${d.stats.returned||0} returned.${d.stats.recent_open?' '+d.stats.recent_open+' open order(s) created in the last 24 hours. Check for a duplicate before submitting.':''}</p>`}catch(e){target.textContent=e.message}}}
// Mark navigation choices without changing storefront routes.
document.querySelector('#tabs').addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;document.querySelectorAll('#tabs button').forEach(b=>b.classList.toggle('active',b===button))});
async function courierCredentials(i,environment='production'){try{const c=courierList[i],d=await api('admin/courier-credentials?'+new URLSearchParams({courierId:c.id,environment}));view.innerHTML=`<section><button onclick="couriers()">← Couriers</button><h2>${esc(c.name)} · API credentials</h2><p>Owner-only. Credentials are encrypted on the server and never displayed back in the form.</p><label for="credentialenvironment">Environment</label><select id="credentialenvironment"><option value="production" ${environment==='production'?'selected':''}>Production</option><option value="sandbox" ${environment==='sandbox'?'selected':''}>Sandbox</option></select><p class="notice">${d.saved?'Credentials saved · '+esc(new Date(d.updatedAt).toLocaleString('en-GB',{timeZone:'Asia/Dhaka'})):'No credentials saved for this environment.'}<br>Live API connection: not verified. Saving credentials does not book parcels or enable live tracking.</p><form id="credentialsform" autocomplete="off"><label for="baseUrl">Base URL</label><input id="baseUrl" value="${esc(d.baseUrl)}" readonly><label for="clientId">Client ID</label><input id="clientId" name="clientId" type="password" autocomplete="off" maxlength="500" ${d.saved?'':'required'} placeholder="${d.saved?'Saved — leave blank to keep':'Enter Client ID'}"><label for="clientSecret">Client Secret</label><input id="clientSecret" name="clientSecret" type="password" autocomplete="new-password" maxlength="2000" ${d.saved?'':'required'} placeholder="${d.saved?'Saved — leave blank to keep':'Enter Client Secret'}"><label for="clientContext">Client Context</label><input id="clientContext" name="clientContext" type="password" autocomplete="off" maxlength="2000" ${d.saved?'':'required'} placeholder="${d.saved?'Saved — leave blank to keep':'Enter Client Context'}"><p><button ${d.secureStorage?'':'disabled'}>Save encrypted credentials</button></p></form><p>${d.secureStorage?'Secure storage is ready.':'Secure storage must be configured before saving.'} Official API documentation is needed to implement and verify authentication, booking and status tracking.</p></section>`;document.querySelector('#credentialenvironment').onchange=e=>courierCredentials(i,e.target.value);document.querySelector('#credentialsform').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{const payload={courierId:c.id,environment,...Object.fromEntries(new FormData(e.target))};await api('admin/courier-credentials','POST',payload);e.target.reset();say('Credentials saved encrypted. Live API has not been verified.');courierCredentials(i,environment)}catch(e){fail(e)}finally{button.disabled=false}}}catch(e){fail(e)}}
const selectedIds=()=>[...document.querySelectorAll('[data-select-order]:checked')].map(c=>c.dataset.selectOrder);
async function bulkAction(kind){const ids=selectedIds();if(!ids.length)return say('Select at least one order on this page.');const value=document.querySelector(kind==='status'?'#bulkstatus':'#bulkcourier').value;if(!value)return say('Choose a status or courier first.');const result=document.querySelector('#bulkresult');const buttons=[...document.querySelectorAll('.bulkbar button')];const disabledBefore=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);const outcomes=[];for(const id of ids){try{if(kind==='status')await api('admin/orders/'+id,'PATCH',{status:value});else await api('admin/ops/order/'+id,'POST',{action:'assign-courier',courierId:value});outcomes.push(orderRef(currentOrderRows.find(o=>o.id===id)||{id})+': updated')}catch(e){outcomes.push(orderRef(currentOrderRows.find(o=>o.id===id)||{id})+': '+e.message)}if(!result.isConnected)break;result.textContent=outcomes.join('\n')}buttons.forEach((b,i)=>b.disabled=disabledBefore[i]);say('Bulk action finished. Each result is shown below; refresh the list to see changes.')}
async function bulkPrint(mode){const ids=selectedIds();if(!ids.length)return say('Select orders to print.');if(ids.length>50)return say('Print at most 50 orders at once.');const w=window.open('','_blank');if(!w)return say('Allow pop-ups to print.');w.document.write('<p>Preparing documents…</p>');try{const docs=[];for(const id of ids)docs.push(await api('admin/orders/'+id));w.document.open();w.document.write(`<!doctype html><html><meta charset="utf-8"><title>Siore ${mode==='packing'?'packing slips':'invoices'}</title><style>body{font:14px Arial;margin:25px}article{break-after:page;padding:20px}article:last-child{break-after:auto}table{border-collapse:collapse;width:100%}td,th{border-bottom:1px solid #ddd;padding:12px;text-align:left}p{line-height:1.8}@media print{button{display:none}}</style><button onclick="print()">Print / Save PDF</button>${docs.map(d=>{const o=d.order;return `<article><h1>siore✳ · ${mode==='packing'?'Packing slip':'Invoice'}</h1><p>${esc(orderRef(o))}<br>${esc(o.name)} · ${esc(o.phone)}<br>${esc(o.address)}</p><p>Courier: ${esc(o.courier_name||'Unassigned')} · ${esc(o.consignment||'')}<br>Status: ${esc(o.status)} · Weight: ${o.weight_grams?o.weight_grams/1000+' kg':'Not set'}</p><table><tr><th>Product / variant</th><th>SKU</th><th>Qty</th>${mode==='invoice'?'<th>Amount</th>':'<th>Checked</th>'}</tr>${d.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${esc(i.sku)}</td><td>${i.qty}</td><td>${mode==='invoice'?'৳'+i.price*i.qty:'□'}</td></tr>`).join('')}</table>${mode==='invoice'?`<p>Subtotal ৳${o.subtotal} − discount ৳${o.discount||0} + delivery ৳${o.shipping}<br>Total ৳${o.total}<br>Recorded net receipts ৳${d.finance?.paid||0}<br>Balance due ৳${d.finance?.due??o.total}</p><p>Invoice is not a courier settlement or payment receipt.</p>`:`<p>Notes: ${esc(o.notes)}</p><p>Packed by: __________________ &nbsp; Date: __________</p>`}</article>`}).join('')}</html>`);w.document.close()}catch(e){w.document.body.textContent=e.message;fail(e)}}
function bdLocalInput(iso){return new Date(new Date(iso).getTime()+21600000).toISOString().slice(0,16)}
async function orderOperations(id){try{const d=await api('admin/orders/'+id),o=d.order,x=await api('admin/ops/order/'+id),f=x.finance;const relevant=x.courierEvents.find(e=>e.courier_id===o.courier_id&&e.consignment===o.consignment);const state=!relevant?'Unrecorded':!relevant.mapped_status?'Needs mapping':relevant.mapped_status===o.status?'Matched':'Mismatch';const paymentKey=crypto.randomUUID();view.innerHTML=`<section><button id="backdetail">← Order details</button><h2>Order operations</h2><p>${esc(orderRef(o))} · ${esc(o.name)} · <span class="badge">${esc(o.status)}</span></p><div class="metrics"><div class="metric">Order total<strong>৳${o.total}</strong></div><div class="metric">Net receipts<strong>৳${f.paid}</strong></div><div class="metric">Balance due<strong>৳${f.due}</strong></div><div class="metric">Credit<strong>৳${f.credit}</strong></div><div class="metric">Initial courier COD after advances<strong>৳${f.courierCollectible}</strong></div></div><p>Receipts/refunds are manually recorded. Courier settlement is separate and does not automatically mark customer payments. Closed orders have no balance due; remaining receipts are shown as credit for review/refund. Initial courier COD does not allocate later refunds.</p><h3>Courier booking</h3><p>Booking: ${esc(o.booking_status)} · Tracking ID: ${esc(o.consignment||'Not booked')}<br>Courier API payment: ${esc(o.courier_payment_status)}<br>Manual settlement: ${esc(o.manual_settlement_status)}</p><p>${esc(x.shipping.reason)}</p>${o.status==='Ready to Ship'&&allowed('courier.book')?`<button disabled>Send to Courier · API setup required</button>`:''}<div class="opsgrid">${allowed('orders.edit')?`<form id="discountform"><h3>Manual discount</h3><label for="orderdiscount">Discount (BDT)</label><input id="orderdiscount" type="number" min="0" max="${o.subtotal}" step="1" value="${o.discount||0}" required>${field('Reason for change','discountreason')}<p>Product subtotal ৳${o.subtotal}. Delivery fee stays separate. Updates invoices and balance; existing courier bookings need separate reconciliation.</p><button>Save discount</button></form>`:''}${allowed('payments.write')?`<form id="paymentform"><h3>Advance / Collection / Refund</h3><label for="paymentkind">Type</label><select id="paymentkind" name="kind"><option>Advance</option><option>Collection</option><option>Refund</option></select>${field('Amount (BDT)','paymentamount',1,'number')}${field('Transaction / receipt reference','paymentreference')}<p><button>Record transaction</button></p></form>`:''}${allowed('orders.edit')?`<form id="followupform"><h3>Follow-up</h3><label for="followupreason">Reason</label><select id="followupreason" name="reason">${['No answer','Incomplete address','Awaiting confirmation','Call later','Other'].map(s=>`<option ${s===o.followup_reason?'selected':''}>${s}</option>`).join('')}</select>${field('Next follow-up (Bangladesh time)','followupat',bdLocalInput(o.followup_at||new Date().toISOString()),'datetime-local')}<label for="followupnote">Note</label><textarea id="followupnote">${esc(o.followup_note)}</textarea><label><input id="followupdone" type="checkbox" style="width:auto" ${o.followup_done?'checked':''}> Follow-up completed</label><p><button>Save follow-up</button></p></form>`:''}<form id="packingform"><h3>Packing checklist</h3><p>Match actual product, colour/size/letter, SKU and quantity before checking each line.</p>${d.items.map(i=>`<div class="checkrow"><input type="checkbox" id="pack${i.id}" data-pack="${i.id}" ${x.packing.find(p=>p.item_id===i.id)?.checked?'checked':''} ${allowed('packing.write')?'':'disabled'}><label for="pack${i.id}">${esc(i.name)}<br>${esc(i.sku)} · Qty ${i.qty}</label></div>`).join('')}<p><button ${allowed('packing.write')?'':'disabled'}>Save packing checks</button></p></form>${allowed('orders.status')||allowed('orders.edit')?`<form id="returnreasonform"><h3>Return reason</h3><label for="returnreason">Reason</label><select id="returnreason">${x.returnReasons.map(r=>`<option ${r===o.return_reason?'selected':''}>${r}</option>`).join('')}</select><p><button ${['Return Requested','Returned'].includes(o.status)?'':'disabled'}>Save return reason</button></p><p>Move to Return Requested before recording a reason. A reason is required before completing Returned.</p></form>`:''}</div><h3>Courier status verification</h3><p>Store status: <strong>${esc(o.status)}</strong> · Comparison: <span class="badge ${state==='Mismatch'?'danger':''}">${state}</span></p><p>Courier status: ${esc(relevant?.raw_status||'Not recorded')} · Mapped: ${esc(relevant?.mapped_status||'—')}<br>Evidence source: ${esc(relevant?.source||'None')} · ${relevant?esc(new Date(relevant.at).toLocaleString('en-GB',{timeZone:'Asia/Dhaka'})):''}</p><p class="notice">A match to a manually entered courier status is a manual comparison, not API verification. Old evidence from a different courier or consignment is excluded. Reconciliation changes the store status only when its normal transition and packing/return requirements are satisfied.</p>${allowed('courier.verify')?`<form id="couriercheckform">${field('Exact status shown in courier panel','rawstatus')}<label for="mappedstatus">Equivalent store status</label><select id="mappedstatus"><option value="">Unknown / needs mapping</option>${orderStatuses.map(s=>`<option>${s}</option>`).join('')}</select>${field('Evidence reference / panel check note','courierreference')}<p><button>Record manual courier status</button></p></form>${relevant?.mapped_status&&relevant.mapped_status!==o.status&&allowed('orders.status')?'<button id="reconcile">Apply latest mapped status to store</button>':''}`:''}<h3>Courier evidence history</h3><div class="scroll"><table><tr><th>Status</th><th>Mapped</th><th>Consignment</th><th>Source / checked by</th><th>Reference</th></tr>${x.courierEvents.map(e=>`<tr><td>${esc(e.raw_status)}</td><td>${esc(e.mapped_status||'Unknown')}</td><td>${esc(e.consignment)}</td><td>${esc(e.source)} · ${esc(e.actor)}</td><td>${esc(e.reference)}</td></tr>`).join('')}</table></div>${allowed('settlements.write')?`<form id="settlementform"><h3>Courier settlement · cumulative amounts for this order</h3><p>Enter actual totals to date; saving replaces this order’s totals and records an audit entry. Expected collectible after advances: ৳${f.courierCollectible}.</p>${field('Actually collected by courier','settlementcollected',x.settlement?.collected||0,'number')}${field('Delivery fee','settlementdelivery',x.settlement?.delivery_fee||0,'number')}${field('COD fee','settlementcod',x.settlement?.cod_fee||0,'number')}${field('Return fee','settlementreturn',x.settlement?.return_fee||0,'number')}${field('Net remitted to Siore (negative if paid to courier)','settlementremitted',x.settlement?.remitted||0,'number')}${field('Statement / settlement reference','settlementreference',x.settlement?.reference)}<p><button>Save settlement totals</button></p></form>`:''}<h3>Recorded payments</h3><table><tr><th>Type</th><th>Amount</th><th>Reference</th><th>By / time</th></tr>${x.payments.map(p=>`<tr><td>${esc(p.kind)}</td><td>৳${p.amount}</td><td>${esc(p.reference)}</td><td>${esc(p.actor)}<br>${esc(new Date(p.at).toLocaleString('en-GB',{timeZone:'Asia/Dhaka'}))}</td></tr>`).join('')}</table><h3>Quick customer messages</h3><label for="messagetype">Template</label><select id="messagetype"><option value="confirm">Order summary</option><option value="dispatch">Delivery update</option>${!['Cancelled','Returned'].includes(o.status)?'<option value="payment">Payment reminder</option>':''}</select><label for="quickmessage">Review / edit before sending</label><textarea id="quickmessage" rows="7"></textarea><p><button id="copymessage">Copy message</button></p><p>Copy only. No message is sent automatically.</p></section>`;
document.querySelector('#backdetail').onclick=()=>detail(id);const send=async payload=>{await api('admin/ops/order/'+id,'POST',payload);say('Saved.');orderOperations(id)};
if(document.querySelector('#discountform'))document.querySelector('#discountform').onsubmit=async e=>{e.preventDefault();try{await send({action:'discount',amount:Number(document.querySelector('#orderdiscount').value),reason:document.querySelector('#discountreason').value})}catch(e){fail(e)}};
if(document.querySelector('#paymentform'))document.querySelector('#paymentform').onsubmit=async e=>{e.preventDefault();try{await send({action:'payment',requestKey:paymentKey,kind:document.querySelector('#paymentkind').value,amount:Number(document.querySelector('#paymentamount').value),reference:document.querySelector('#paymentreference').value})}catch(e){fail(e)}};
if(document.querySelector('#followupform'))document.querySelector('#followupform').onsubmit=async e=>{e.preventDefault();try{await send({action:'followup',reason:document.querySelector('#followupreason').value,note:document.querySelector('#followupnote').value,at:new Date(document.querySelector('#followupat').value+':00+06:00').toISOString(),done:document.querySelector('#followupdone').checked})}catch(e){fail(e)}};
document.querySelector('#packingform').onsubmit=async e=>{e.preventDefault();try{await send({action:'packing',items:[...document.querySelectorAll('[data-pack]')].map(c=>({id:c.dataset.pack,checked:c.checked}))})}catch(e){fail(e)}};
if(document.querySelector('#returnreasonform'))document.querySelector('#returnreasonform').onsubmit=async e=>{e.preventDefault();try{await send({action:'return-reason',reason:document.querySelector('#returnreason').value})}catch(e){fail(e)}};
if(document.querySelector('#couriercheckform'))document.querySelector('#couriercheckform').onsubmit=async e=>{e.preventDefault();try{await send({action:'courier-status',rawStatus:document.querySelector('#rawstatus').value,mappedStatus:document.querySelector('#mappedstatus').value,reference:document.querySelector('#courierreference').value})}catch(e){fail(e)}};
if(document.querySelector('#reconcile'))document.querySelector('#reconcile').onclick=async()=>{try{await send({action:'reconcile',eventId:relevant.id})}catch(e){fail(e)}};
if(document.querySelector('#settlementform'))document.querySelector('#settlementform').onsubmit=async e=>{e.preventDefault();try{await send({action:'settlement',collected:Number(document.querySelector('#settlementcollected').value),deliveryFee:Number(document.querySelector('#settlementdelivery').value),codFee:Number(document.querySelector('#settlementcod').value),returnFee:Number(document.querySelector('#settlementreturn').value),remitted:Number(document.querySelector('#settlementremitted').value),reference:document.querySelector('#settlementreference').value})}catch(e){fail(e)}};
const templates={confirm:`Siore থেকে আপনার অর্ডারের তথ্য:\nঅর্ডার: ${orderRef(o)}\n${d.items.map(i=>i.name+' × '+i.qty).join('\n')}\nমোট: ৳${o.total}\nঅগ্রিমসহ রেকর্ড করা net payment: ৳${f.paid}\nবাকি: ৳${f.due}\nবর্তমান অবস্থা: ${o.status}`,dispatch:`আপনার Siore অর্ডার ${orderRef(o)}-এর বর্তমান অবস্থা: ${o.status}।\nCourier: ${o.courier_name||'এখনো নির্ধারিত হয়নি'}\nTracking: ${o.consignment||'এখনো পাওয়া যায়নি'}\n${o.tracking_url||''}`,payment:`আপনার Siore অর্ডার ${orderRef(o)}-এ আমাদের রেকর্ড অনুযায়ী বাকি ৳${f.due}। আগে পরিশোধ করে থাকলে transaction reference জানাবেন।`};const render=()=>document.querySelector('#quickmessage').value=templates[document.querySelector('#messagetype').value];document.querySelector('#messagetype').onchange=render;render();document.querySelector('#copymessage').onclick=async()=>{try{await navigator.clipboard.writeText(document.querySelector('#quickmessage').value);say('Message copied.')}catch{document.querySelector('#quickmessage').select();say('Select the message and copy it manually.')}};
}catch(e){fail(e)}}
async function followups(){try{const d=await api('admin/ops/queue?kind=followup');view.innerHTML=`<section><h2>Follow-up queue</h2><p>Open, incomplete follow-ups · Bangladesh time · Up to ${d.limit} records.</p><label for="followupfilter">Show</label><select id="followupfilter"><option value="all">All scheduled</option><option value="due">Due now / overdue</option><option value="future">Upcoming</option></select><div class="scroll"><table><tr><th>Customer / order</th><th>Next contact</th><th>Reason / note</th><th>Status</th><th></th></tr>${d.orders.map(o=>`<tr data-followup-at="${esc(o.followup_at)}"><td>${esc(o.name)}<br>${esc(o.phone)}<br>${esc(orderRef(o))}</td><td class="${new Date(o.followup_at)<new Date()?'dangertext':''}">${esc(new Date(o.followup_at).toLocaleString('en-GB',{timeZone:'Asia/Dhaka'}))}</td><td>${esc(o.followup_reason)}<br>${esc(o.followup_note)}</td><td>${esc(o.status)}</td><td><button data-ops="${o.id}">Open</button></td></tr>`).join('')}</table></div>${d.orders.length?'':'<p>No incomplete follow-ups.</p>'}</section>`;document.querySelectorAll('[data-ops]').forEach(b=>b.onclick=()=>orderOperations(b.dataset.ops));document.querySelector('#followupfilter').onchange=e=>document.querySelectorAll('[data-followup-at]').forEach(row=>{const due=new Date(row.dataset.followupAt)<=new Date();row.hidden=e.target.value==='due'?!due:e.target.value==='future'?due:false})}catch(e){fail(e)}}
async function courierChecks(){try{const d=await api('admin/ops/queue?kind=verification');view.innerHTML=`<section><h2>Courier status checks</h2><p class="notice">Compare store status with the most recent courier evidence for the same courier and consignment. Manual matches are not API verified. Live API status sync is awaiting official documentation and a tested integration.</p><label for="verificationfilter">Comparison</label><select id="verificationfilter"><option value="">All</option>${['Mismatch','Matched','Unrecorded','Needs mapping'].map(s=>`<option>${s}</option>`).join('')}</select><div class="scroll"><table><tr><th>Order / customer</th><th>Courier / tracking</th><th>Store status</th><th>Courier status / mapped</th><th>Comparison</th><th>Evidence source</th><th></th></tr>${d.orders.map(o=>`<tr data-verification="${o.verification}"><td>${esc(orderRef(o))}<br>${esc(o.name)}</td><td>${esc(o.courier_name)}<br>${esc(o.consignment)}</td><td>${esc(o.status)}</td><td>${esc(o.raw_status||'—')}<br>${esc(o.mapped_status||'—')}</td><td><span class="badge ${o.verification==='Mismatch'?'danger':''}">${o.verification}</span></td><td>${esc(o.courier_source||'No evidence')}<br>${o.courier_checked_at?esc(new Date(o.courier_checked_at).toLocaleString('en-GB',{timeZone:'Asia/Dhaka'})):''}</td><td><button data-ops="${o.id}">Review</button></td></tr>`).join('')}</table></div><p>Showing up to ${d.limit} assigned consignments. Orders without a tracking number are not included.</p></section>`;document.querySelectorAll('[data-ops]').forEach(b=>b.onclick=()=>orderOperations(b.dataset.ops));document.querySelector('#verificationfilter').onchange=e=>document.querySelectorAll('[data-verification]').forEach(row=>row.hidden=!!e.target.value&&row.dataset.verification!==e.target.value)}catch(e){fail(e)}}
let settlementQuery={};async function settlementReport(){try{const d=await api('admin/ops/settlements?'+new URLSearchParams(settlementQuery)),c=allowed('couriers.read')?await api('admin/couriers'):[];const total=d.reduce((n,r)=>n+r.unsettled,0);view.innerHTML=`<section><h2>Courier settlements</h2>${filterForm(settlementQuery,c,'settlementfilters')}<p class="notice">Cumulative actual collection − delivery fee − COD fee − return fee − net remitted. Positive balance: due to Siore. Negative balance: review over-remittance or amount payable to courier. These manually entered records are not API-confirmed bank receipts.</p><h3>Unsettled balance: ৳${total}</h3><div class="scroll"><table><tr><th>Courier / order</th><th>Collection</th><th>Delivery / COD / return fees</th><th>Net remitted</th><th>Unsettled</th><th>Reference</th><th></th></tr>${d.map(r=>`<tr><td>${esc(r.courier_name)}<br>${esc(r.display_id||r.id)}<br>${esc(r.consignment)}</td><td>৳${r.collected}</td><td>৳${r.delivery_fee} / ৳${r.cod_fee} / ৳${r.return_fee}</td><td>৳${r.remitted}</td><td>৳${r.unsettled}</td><td>${esc(r.reference)}</td><td><button data-ops="${r.id}">Open</button></td></tr>`).join('')}</table></div></section>`;document.querySelector('#settlementfilters').onsubmit=e=>{e.preventDefault();settlementQuery=Object.fromEntries(new FormData(e.target));settlementReport()};document.querySelector('[data-reset]').onclick=()=>{settlementQuery={};settlementReport()};document.querySelectorAll('[data-ops]').forEach(b=>b.onclick=()=>orderOperations(b.dataset.ops))}catch(e){fail(e)}}
let returnQuery={};async function returnReport(){try{const d=await api('admin/ops/return-report?'+new URLSearchParams(returnQuery)),c=allowed('couriers.read')?await api('admin/couriers'):[];view.innerHTML=`<section><h2>Return reasons & products</h2>${filterForm(returnQuery,c,'returnfilters')}<p class="notice">Return Requested and Returned orders only. Product values are not verified refunds, courier loss or profit. Filters use current order status and the selected date basis.</p><h3>Reasons by channel</h3><table><tr><th>Reason</th><th>Channel</th><th>Orders</th><th>Product value</th></tr>${d.reasons.map(r=>`<tr><td>${esc(r.reason)}</td><td>${esc(r.source)}</td><td>${r.orders}</td><td>৳${r.product_value}</td></tr>`).join('')}</table><h3>Products / variants returned or requested</h3><table><tr><th>Product</th><th>SKU</th><th>Orders</th><th>Units</th><th>Value</th></tr>${d.products.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.sku)}</td><td>${r.orders}</td><td>${r.units}</td><td>৳${r.product_value}</td></tr>`).join('')}</table></section>`;document.querySelector('#returnfilters').onsubmit=e=>{e.preventDefault();returnQuery=Object.fromEntries(new FormData(e.target));returnReport()};document.querySelector('[data-reset]').onclick=()=>{returnQuery={};returnReport()}}catch(e){fail(e)}}
let posActive=[],posRecalc=()=>{};
function appendPosItem(id,qty=1,increment=true){const p=posActive.find(p=>p.id===id);if(!p||p.stock<1){say('An unavailable draft product could not be restored. Review the item list.');return}const container=document.querySelector('#positems');const existing=[...container.querySelectorAll('[data-product]')].find(el=>el.dataset.product===id);const max=Math.min(p.stock,50);if(existing){existing.value=Math.min(max,increment?Number(existing.value)+qty:qty)}else{if(container.querySelectorAll('[data-product]').length>=30){say('Add at most 30 different products per order.');return}const row=document.createElement('div');row.className='positem';row.innerHTML=`<div><strong>${esc(p.name)}${p.variant_label?' — '+esc(p.variant_label):''}</strong><br><small>${esc(p.sku)} · ৳${p.price} each · Available ${p.stock}</small></div><div><label for="posqty${id}">Quantity</label><input id="posqty${id}" type="number" data-product="${id}" data-price="${p.price}" min="1" max="${max}" step="1" value="${Math.min(qty,max)}" required></div><button type="button" data-remove>Remove</button>`;container.append(row);row.querySelector('[data-product]').oninput=()=>posRecalc();row.querySelector('[data-remove]').onclick=()=>{row.remove();document.querySelector('#posempty').hidden=container.children.length>0;posRecalc();document.querySelector('#orderform').dispatchEvent(new Event('input',{bubbles:true}))}}document.querySelector('#posempty').hidden=container.children.length>0;posRecalc();document.querySelector('#orderform').dispatchEvent(new Event('input',{bubbles:true}))}
async function manualStatus(id){try{const d=await api('admin/orders/'+id),o=d.order;const next=statusNext;view.innerHTML=`<section><button onclick="orders()">← Orders</button><h2>Manual status update · ${esc(orderRef(o))}</h2><p>${esc(o.name)} · ${esc(o.phone)}</p><p>Current status: <strong>${esc(o.status)}</strong><br>Parcel weight: ${o.weight_grams?o.weight_grams/1000+' kg':'Not set'}</p><form id="manualstatusform"><label for="manualstatus">Next allowed status</label><select id="manualstatus">${next[o.status].map(s=>`<option>${s}</option>`).join('')}</select><p><button ${next[o.status].length?'':'disabled'}>Save manual status</button></p></form><p>Each change is logged. Packing checks and product weights are required before Ready to Ship; a return reason is required before Returned. This changes the store status, not the courier’s API status.</p><button id="manualops">Open packing / return checks</button> <button id="manualedit" ${allowed('orders.edit')?'':'disabled'}>Edit customer / courier details</button></section>`;document.querySelector('#manualstatusform').onsubmit=async e=>{e.preventDefault();try{await api('admin/orders/'+id,'PATCH',{status:document.querySelector('#manualstatus').value});say('Manual status updated.');manualStatus(id)}catch(e){fail(e)}};document.querySelector('#manualops').onclick=()=>orderOperations(id);document.querySelector('#manualedit').onclick=()=>editOrder(o)}catch(e){fail(e)}}

let returnState='awaiting',returnSearch='';
async function returnQueue(state=returnState){try{returnState=state;const data=await api('admin/ops/returns?'+new URLSearchParams({state,q:returnSearch}));view.innerHTML=`<section><h2>Return receiving & inquiries</h2><p>Returned status opens this queue. Stock is added only after physical inspection, for good units. Damaged or missing units open courier inquiries.</p><form id="returnfilters"><label for="returnsearch">Old invoice, order / RMA number, tracking ID, customer or phone</label><input id="returnsearch" value="${esc(returnSearch)}"><label for="returnstate">Show</label><select id="returnstate">${[['awaiting','Awaiting parcel / inspection'],['inquiry','Open inquiries'],['received','Inspected returns'],['legacy','Legacy inventory review'],['all','All returns']].map(([v,t])=>`<option value="${v}" ${v===state?'selected':''}>${t}</option>`).join('')}</select><p><button>Search / filter</button></p></form><div class="scroll"><table><tr><th>Return / old invoice</th><th>Customer</th><th>Courier / tracking</th><th>Receiving</th><th>Inquiries</th><th></th></tr>${data.orders.map(o=>`<tr><td>${esc(orderRef(o).replace(/^SIO-/,'RMA-'))}<br>${esc(orderRef(o).replace(/^SIO-/,'INV-'))}</td><td>${esc(o.name)}<br>${esc(o.phone)}</td><td>${esc(o.courier_name||'Unassigned')}<br>${esc(o.consignment||'No tracking ID')}</td><td>${o.received_at?esc(o.kind)+' · '+esc(new Date(o.received_at).toLocaleDateString('en-GB',{timeZone:'Asia/Dhaka'})):'Awaiting inspection'}${o.legacy?'<br><span class="badge warning">Legacy stock review</span>':''}</td><td>${o.open_issues}</td><td><button data-return="${o.id}">Open / receive</button></td></tr>`).join('')}</table></div><p>${data.orders.length} results · maximum ${data.limit}. Narrow search when needed.</p></section>`;document.querySelector('#returnfilters').onsubmit=e=>{e.preventDefault();returnSearch=document.querySelector('#returnsearch').value;returnQueue(document.querySelector('#returnstate').value)};document.querySelectorAll('[data-return]').forEach(b=>b.onclick=()=>returnDetail(b.dataset.return))}catch(e){fail(e)}}
async function returnDetail(id){try{const d=await api('admin/ops/returns/'+id),o=d.order,c=d.returnCase;view.innerHTML=`<section><button onclick="returnQueue()">← Return queue</button><h2>${esc(orderRef(o).replace(/^SIO-/,'RMA-'))} · Return parcel</h2><p>Original invoice: ${esc(orderRef(o).replace(/^SIO-/,'INV-'))}<br>${esc(o.name)} · ${esc(o.phone)}<br>Courier: ${esc(o.courier_name||'Unassigned')} · Tracking: ${esc(c?.consignment||o.consignment||'Not recorded')}<br>Return reason: ${esc(o.return_reason)}</p>${d.legacy?'<p class="notice">Legacy return: the previous system already credited stock when this order became Returned. Receiving here adds no stock again. Check the inventory separately for damaged, missing or previously sold quantities.</p>':''}<p><button id="returninvoice">Open original invoice</button>${c?.received_at?' <button id="returnprint">Print return receipt / claim pack</button>':''}</p>${!c?.received_at?`<form id="returnreceive"><h3>Receive and inspect</h3><p>Check the actual parcel against each SKU and quantity. Every unit must be classified. Save is final; do not mark missing stock as good.</p><label for="returnkind">Inspection type</label><select id="returnkind"><option>Received</option><option>Lost parcel</option></select><p><button type="button" id="markgood">All items checked good</button> <button type="button" id="marklost">Mark entire parcel missing</button></p><div class="scroll"><table><tr><th>Product / SKU</th><th>Expected</th><th>Good</th><th>Damaged</th><th>Missing</th></tr>${d.items.map(i=>`<tr data-return-item="${i.id}"><td>${esc(i.name)}<br>${esc(i.sku)}</td><td>${i.qty}</td>${['good','damaged','missing'].map(k=>`<td><label for="${k}${i.id}">${k}</label><input id="${k}${i.id}" data-condition="${k}" type="number" min="0" max="${i.qty}" step="1" value="0" required></td>`).join('')}</tr>`).join('')}</table></div>${field('Courier return handover / loss reference','returnreference')}<label for="returnnote">Inspection / damage / missing details</label><textarea id="returnnote" maxlength="2000"></textarea><label for="returnphotos">Evidence photos (up to 8 · JPG/PNG/WebP · 4 MB each)</label><input id="returnphotos" type="file" accept="image/jpeg,image/png,image/webp" multiple><label><input type="checkbox" id="returnconfirm" required style="width:auto"> I checked the quantities and physically received good/damaged units, or verified the courier loss reference.</label><p id="returnpreview" role="status"></p><button ${allowed('returns.receive')?'':'disabled'}>Save inspection & add good stock</button></form>`:`<h3>${esc(c.kind)} · ${esc(new Date(c.received_at).toLocaleString('en-GB',{timeZone:'Asia/Dhaka'}))}</h3><p>Checked by ${esc(c.received_by)}<br>Reference: ${esc(c.reference)}<br>${esc(c.note)}</p><table><tr><th>SKU / product</th><th>Good</th><th>Damaged</th><th>Missing</th></tr>${d.items.map(i=>`<tr><td>${esc(i.sku)} · ${esc(i.name)}</td><td>${i.good}</td><td>${i.damaged}</td><td>${i.missing}</td></tr>`).join('')}</table><p>${c.evidence.map(url=>`<a href="${esc(url)}" target="_blank" rel="noopener"><img src="${esc(url)}" alt="Return evidence" width="110"></a>`).join('')}</p>`}${c?.received_at&&(allowed('returns.receive')||allowed('claims.manage'))?`<form id="addevidence"><h3>Add further evidence photos</h3><label for="extraphotos">Additional photos (8 total per return)</label><input id="extraphotos" type="file" accept="image/jpeg,image/png,image/webp" multiple required>${field('Evidence / follow-up reference','extraref')}<p><button>Add evidence</button></p></form>`:''}<h3>Courier inquiries / compensation claims</h3><p>Claims are recorded manually. Print the claim pack to submit to the courier. Compensation does not mark customer payment or courier settlement. Default requested value uses original unit price; adjust to the actual claim before submission.</p>${d.issues.length?d.issues.map(i=>`<form class="returnclaim" data-issue="${i.id}"><h3>${esc(i.kind)} · ${esc(i.name)} / ${esc(i.sku)} × ${i.qty}</h3><p>Inquiry ${esc(i.id)} · updated by ${esc(i.updated_by)}</p><label for="claimstatus${i.id}">Claim status</label><select name="status" id="claimstatus${i.id}">${d.statuses.map(s=>`<option ${s===i.status?'selected':''}>${s}</option>`).join('')}</select><label for="requested${i.id}">Requested compensation (BDT)</label><input id="requested${i.id}" name="requested" type="number" min="0" step="1" value="${i.requested}" required><label for="paid${i.id}">Compensation received to date (BDT)</label><input id="paid${i.id}" name="paid" type="number" min="0" step="1" value="${i.paid}" required><label for="recovered${i.id}">Physically recovered good quantity (only on closing)</label><input id="recovered${i.id}" name="recovered" type="number" min="0" max="${i.qty}" step="1" value="${i.recovered}" required><label for="claimref${i.id}">Courier claim / payment / resolution reference</label><input id="claimref${i.id}" name="reference" maxlength="200" value="${esc(i.reference)}"><label for="claimnote${i.id}">Follow-up / final resolution and remaining loss</label><textarea id="claimnote${i.id}" name="note" minlength="5" maxlength="2000" required>${esc(i.note)}</textarea><p>Close only after recording the outcome. Recovered good quantities add stock once; other quantities stay excluded. Closed inquiries cannot be reopened.</p><button ${allowed('claims.manage')&&i.status!=='Closed'?'':'disabled'}>Save inquiry</button><details><summary>Claim history</summary>${d.history.filter(h=>h.issue_id===i.id).map(h=>`<p>${esc(h.status)} · ${esc(h.at)} · ${esc(h.actor)}<br>Requested ৳${h.requested} · Compensation ৳${h.paid} · Recovered ${h.recovered}<br>${esc(h.reference)} · ${esc(h.note)}</p>`).join('')}</details></form>`).join(''):'<p>No damage or missing-item inquiries recorded.</p>'}</section>`;
document.querySelector('#returninvoice').onclick=async()=>{try{invoice(await api('admin/orders/'+id))}catch(e){fail(e)}};if(document.querySelector('#returnprint'))document.querySelector('#returnprint').onclick=()=>printReturn(d);
if(document.querySelector('#returnreceive')){const f=document.querySelector('#returnreceive');const getLines=()=>[...f.querySelectorAll('[data-return-item]')].map(row=>({id:row.dataset.returnItem,...Object.fromEntries([...row.querySelectorAll('[data-condition]')].map(x=>[x.dataset.condition,Number(x.value)]))}));f.oninput=()=>{const lines=getLines();document.querySelector('#returnpreview').textContent='Good stock to add: '+(d.legacy?0:lines.reduce((n,i)=>n+i.good,0))+' · Damaged: '+lines.reduce((n,i)=>n+i.damaged,0)+' · Missing: '+lines.reduce((n,i)=>n+i.missing,0)};document.querySelector('#markgood').onclick=()=>{document.querySelector('#returnkind').value='Received';for(const row of f.querySelectorAll('[data-return-item]'))for(const x of row.querySelectorAll('[data-condition]'))x.value=x.dataset.condition==='good'?x.max:0;f.oninput()};document.querySelector('#marklost').onclick=()=>{document.querySelector('#returnkind').value='Lost parcel';for(const row of f.querySelectorAll('[data-return-item]'))for(const x of row.querySelectorAll('[data-condition]'))x.value=x.dataset.condition==='missing'?x.max:0;f.oninput()};f.onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const files=[...document.querySelector('#returnphotos').files];if(files.length>8)throw Error('Choose at most 8 photos');const evidence=[];for(const file of files){if(file.size>4194304)throw Error('Each photo must be under 4 MB');const response=await fetch('/api/admin/return-media',{method:'POST',headers:{'Content-Type':file.type},body:file});const result=await response.json();if(!response.ok)throw Error(result.error||'Photo upload failed');evidence.push(result.url)}const result=await api('admin/ops/returns/'+id,'POST',{action:'receive',kind:document.querySelector('#returnkind').value,reference:document.querySelector('#returnreference').value,note:document.querySelector('#returnnote').value,items:getLines(),evidence});say('Inspection saved. Good stock added: '+result.stockAdded+(result.legacy?' · Legacy stock requires separate review.':''));returnDetail(id)}catch(e){fail(e)}finally{b.disabled=false}}}
if(document.querySelector('#addevidence'))document.querySelector('#addevidence').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const files=[...document.querySelector('#extraphotos').files];if(files.length+(c.evidence?.length||0)>8)throw Error('At most 8 photos per return');const evidence=[];for(const file of files){if(file.size>4194304)throw Error('Each photo must be under 4 MB');const response=await fetch('/api/admin/return-media',{method:'POST',headers:{'Content-Type':file.type},body:file});const result=await response.json();if(!response.ok)throw Error(result.error||'Photo upload failed');evidence.push(result.url)}await api('admin/ops/returns/'+id,'POST',{action:'evidence',evidence,reference:document.querySelector('#extraref').value});say('Evidence added.');returnDetail(id)}catch(e){fail(e)}finally{b.disabled=false}};
document.querySelectorAll('.returnclaim').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const v=Object.fromEntries(new FormData(f));const result=await api('admin/ops/returns/'+id,'POST',{action:'claim',issueId:f.dataset.issue,...v,requested:Number(v.requested),paid:Number(v.paid),recovered:Number(v.recovered)});say('Inquiry saved. Recovered good stock added: '+result.stockAdded);returnDetail(id)}catch(e){fail(e)}finally{b.disabled=false}})}catch(e){fail(e)}}
function printReturn(d){const w=window.open('','_blank');if(!w)return say('Allow pop-ups to print the return / claim pack.');const o=d.order,c=d.returnCase;w.document.write(`<!doctype html><html><meta charset="utf-8"><title>Return ${esc(orderRef(o))}</title><style>body{font:14px Arial;max-width:900px;margin:30px auto;padding:20px}p{line-height:1.7;white-space:pre-wrap}table{width:100%;border-collapse:collapse}td,th{border:1px solid #ccc;padding:10px;text-align:left}img{max-width:220px;margin:8px}article{break-inside:avoid}@media print{button{display:none}}</style><h1>siore ✳ · Return receipt & courier claim pack</h1><p>Return: ${esc(orderRef(o).replace(/^SIO-/,'RMA-'))}\nOriginal invoice: ${esc(orderRef(o).replace(/^SIO-/,'INV-'))}\nCustomer: ${esc(o.name)} · ${esc(o.phone)}\nCourier: ${esc(o.courier_name||'Unassigned')}\nTracking / consignment: ${esc(c.consignment||o.consignment)}\nReturn reason: ${esc(o.return_reason)}\nInspection: ${esc(c.kind)} · ${esc(c.received_at)}\nChecked by: ${esc(c.received_by)}\nHandover / loss reference: ${esc(c.reference)}\nNotes: ${esc(c.note)}</p>${d.legacy?'<p>Legacy return: inventory was credited by the old workflow. This inspection did not add stock.</p>':''}<table><tr><th>SKU / product</th><th>Expected</th><th>Good</th><th>Damaged</th><th>Missing</th><th>Original unit price</th></tr>${d.items.map(i=>`<tr><td>${esc(i.sku)} · ${esc(i.name)}</td><td>${i.qty}</td><td>${i.good}</td><td>${i.damaged}</td><td>${i.missing}</td><td>৳${i.price}</td></tr>`).join('')}</table><h2>Courier inquiries</h2>${d.issues.map(i=>`<article><h3>${esc(i.kind)} · ${esc(i.sku)} × ${i.qty}</h3><p>ID: ${esc(i.id)}\nStatus: ${esc(i.status)}\nRequested: ৳${i.requested} · Recorded compensation: ৳${i.paid}\nRecovered good: ${i.recovered}\nCourier reference: ${esc(i.reference)}\nResolution / follow-up: ${esc(i.note)}\nUpdated: ${esc(i.updated_at)} · ${esc(i.updated_by)}</p></article>`).join('')}<h2>Claim history</h2>${d.history.map(h=>`<p>Inquiry ${esc(h.issue_id)} · ${esc(h.status)} · ${esc(h.at)} · ${esc(h.actor)}\nRequested ৳${h.requested} · Compensation ৳${h.paid} · Recovered ${h.recovered}\n${esc(h.reference)} · ${esc(h.note)}</p>`).join('')}<h2>Evidence photos</h2>${c.evidence.map(url=>`<img src="${esc(url)}" alt="Return evidence">`).join('')}<p>Prepared from Siore inspection records. Courier liability, approval and payment are not independently verified. No claim is submitted automatically.</p><button onclick="print()">Print / Save PDF</button></html>`);w.document.close()}
